import math

def sigma(n):
    result = 1
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            exponent = 0
            while temp % p == 0:
                exponent += 1
                temp //= p
            result *= (p**(exponent + 1) - 1) // (p - 1)
        p += 1
    if temp > 1:
        result *= (temp**(1 + 1) - 1) // (temp - 1)
    return result

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

candidates = []
m = 2
while len(candidates) < 5:
    if is_square(sigma(m)):
        candidates.append(m)
    m += 1
    if m > 1000: # Safety break
        break

print("Smallest 5 candidates:", candidates)
